   [125]={next_id=126, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我就是从那个时候开始自修心理学的。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [126]={next_id=127, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我无法理解家人做出的决定，不明白为什么要把事故的责任推给这些无辜且勇敢的人。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [127]={next_id=128, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那个时候，西斯那阿姨……也就是我们组织的首领，她送了我一台相机。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [128]={next_id=129, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她告诉我说，要尽快好起来，好好养病。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [129]={next_id=130, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她说人类会看到我们曾做过的一切，即使蒙受了不白之冤，我们也要为了美好而斗争。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [130]={next_id=131, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我还记得那是一件从二手市场淘来的旧货，妈妈看到后，替我换了一台最新的款式。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [131]={next_id=132, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="提到家人，她下意识看向自己的书桌，你看过去，是一个金属的相框。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [132]={next_id=133, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="深黑的边框，搭配银色的支架，看起来冰冷又毫无温度。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [133]={next_id=134, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="里面那张照片有些破旧，还泛着黄，边缘带着些烧焦的痕迹。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
