   [146]={next_id=147, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="之后妈妈出资，为我在当地开了一间咖啡馆……就像是如今莱斯坦斯这间一样。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [147]={next_id=148, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这里成为了我们新的秘密基地，它还是一间临时诊所，我也是在西斯那阿姨的鼓励下尝试着成为一名心理医生的。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [148]={next_id=149, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="尽管我在家人的要求下已经提前完成了学业，但严格说来，我并没有取得毕业证书，也没有获得对应的行医执照。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [149]={next_id=150, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她自嘲般笑了笑。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [150]={next_id=151, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="恐怕我有今天也有这个原因吧。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [151]={next_id=152, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我做不到放下过去，做不到说服自己无视他们的牺牲。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [152]={next_id=153, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我知晓自己的病症有多严重，我也清楚这么下去迟早会死。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [153]={next_id=154, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但是我所渴望的一切都只会将我推向更深的渊薮……尽管和罹难的那些人相比，我并没有说苦难的资格。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_ACT301_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
